package com.univmar.customer.domain;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="customer_contact") public class CustomerContact { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="customer_id",nullable=false) private Customer customer; @Column(nullable=false,length=160) private String name; @Column(length=120) private String role; @Column(length=180) private String email; @Column(length=60) private String phone; protected CustomerContact(){} public CustomerContact(Customer customer,String name,String role,String email,String phone){id=UUID.randomUUID();this.customer=customer;this.name=name;this.role=role;this.email=email;this.phone=phone;} public UUID getId(){return id;} public String getName(){return name;} public String getRole(){return role;} public String getEmail(){return email;} public String getPhone(){return phone;} }
